import "./Admin.css";
import { useEffect, useState } from "react";

function Admin() {
  const [inquiries, setInquiries] = useState([]);
  const [search, setSearch] = useState(""); // Search state
  const [currentPage, setCurrentPage] = useState(1);
  const inquiriesPerPage = 5;

  // Calculate the current inquiries for the page
  const indexOfLastInquiry = currentPage * inquiriesPerPage;
  const indexOfFirstInquiry = indexOfLastInquiry - inquiriesPerPage;

  const filteredInquiries = inquiries.filter(
    (inq) =>
      inq.name.toLowerCase().includes(search.toLowerCase()) ||
      inq.mobile.includes(search)
  );

  const currentInquiries = filteredInquiries.slice(
    indexOfFirstInquiry,
    indexOfLastInquiry
  );

  // Fetch inquiries from backend
  const fetchInquiries = async () => {
    try {
      const response = await fetch("http://127.0.0.1:8000/inquiries");
      const data = await response.json();
      setInquiries(data);
    } catch (error) {
      console.error("Error fetching inquiries:", error);
    }
  };

  // Delete inquiry by id
  const deleteInquiry = async (id) => {
    try {
      const response = await fetch(`http://127.0.0.1:8000/inquiry/${id}`, {
        method: "DELETE",
      });
      if (response.ok) {
        alert("Inquiry deleted successfully!");
        fetchInquiries(); // Refresh list
      } else {
        const err = await response.json();
        alert(err.detail);
      }
    } catch (error) {
      console.error("Error deleting inquiry:", error);
    }
  };

  useEffect(() => {
    fetchInquiries();
  }, []);

  // Calculate total pages
  const totalPages = Math.ceil(filteredInquiries.length / inquiriesPerPage);

  return (
    <div>
      <h1>Admin Panel - Inquiries</h1>

      {/* Search Input */}
      <input
        type="text"
        placeholder="Search by name or mobile..."
        value={search}
        onChange={(e) => setSearch(e.target.value)}
        style={{ marginBottom: "15px", padding: "5px", width: "250px" }}
      />

      {inquiries.length === 0 ? (
        <p>No inquiries found.</p>
      ) : (
        <>
          <table border="1" cellPadding="10">
            <thead>
              <tr>
                <th>Name</th>
                <th>Email</th>
                <th>Mobile</th>
                <th>Message</th>
                <th>Date</th>
                <th>Action</th>
              </tr>
            </thead>
            <tbody>
              {currentInquiries.map((inq) => (
                <tr key={inq._id}>
                  <td>{inq.name}</td>
                  <td>{inq.email}</td>
                  <td>{inq.mobile}</td>
                  <td>{inq.message}</td>
                  <td>{new Date(inq.date).toLocaleString()}</td>
                  <td>
                    <button onClick={() => deleteInquiry(inq._id)}>Delete</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>

          {/* Pagination Buttons */}
          <div style={{ marginTop: "10px" }}>
            {Array.from({ length: totalPages }, (_, i) => i + 1).map((page) => (
              <button
                key={page}
                onClick={() => setCurrentPage(page)}
                style={{
                  margin: "2px",
                  padding: "5px 10px",
                  backgroundColor: currentPage === page ? "#007bff" : "#f0f0f0",
                  color: currentPage === page ? "white" : "black",
                  border: "none",
                  cursor: "pointer",
                }}
              >
                {page}
              </button>
            ))}
          </div>
        </>
      )}
    </div>
  );
}

export default Admin;
